#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <climits>
using namespace std;
using lint = long long;

lint comb[62][62];
lint gainA[32][32], gainB[32][32];
int R, C, N;
string pattern;
lint total;
lint minDelta;
lint result;
vector<pair<lint,lint>> leftPaths[32][2], rightPaths[32][2];
lint pathCount[32][32];

void buildPaths(int x, int y, lint sum, lint w1, lint w2, bool rev) {
    if (x + y == N) {
        leftPaths[x][rev].push_back({sum, w1});
        if (w2) rightPaths[x][rev].push_back({sum, w2});
        return;
    }
    if (x < N) buildPaths(x+1, y, sum + (!rev ? gainA[x+1][y] : 0), w1, (pattern[x+y] != 'B' ? w2 : 0), rev);
    if (y < N) buildPaths(x, y+1, sum + (rev ? gainB[x][y+1] : 0), w1, (pattern[x+y] != 'A' ? w2 : 0), rev);
}

void forwardScan(int x, int y, lint acc, bool rev) {
    if (x + y == N) {
        if (leftPaths[x][rev].empty()) return;
        auto it = lower_bound(leftPaths[x][rev].begin(), leftPaths[x][rev].end(), make_pair((total+1)/2 - acc, 0LL));
        if (it != leftPaths[x][rev].end() && it->second > 0) {
            lint d = abs((it->first + acc) * 2 - total);
            if (d < minDelta) minDelta = d;
        }
        if (it != leftPaths[x][rev].begin()) {
            --it;
            if (it->second > 0) {
                lint d = abs((it->first + acc) * 2 - total);
                if (d < minDelta) minDelta = d;
            }
        }
        return;
    }
    if (x > 0) forwardScan(x-1, y, acc + (!rev ? gainA[x][y] : 0), rev);
    if (y > 0) forwardScan(x, y-1, acc + (rev ? gainB[x][y] : 0), rev);
}

void backwardScan(int x, int y, lint acc, bool rev) {
    if (x + y == N) {
        auto it = lower_bound(rightPaths[x][rev].begin(), rightPaths[x][rev].end(), make_pair((total+1)/2 - acc, 0LL));
        if (it != rightPaths[x][rev].end() && it->second > 0) {
            lint d = abs((it->first + acc) * 2 - total);
            if (d == minDelta) result += it->second;
        }
        if (it != rightPaths[x][rev].begin()) {
            --it;
            if (it->second > 0) {
                lint d = abs((it->first + acc) * 2 - total);
                if (d == minDelta) result += it->second;
            }
        }
        return;
    }
    if (x > 0 && pattern[x+y-1] != 'B') backwardScan(x-1, y, acc + (!rev ? gainA[x][y] : 0), rev);
    if (y > 0 && pattern[x+y-1] != 'A') backwardScan(x, y-1, acc + (rev ? gainB[x][y] : 0), rev);
}

void combine(vector<pair<lint,lint>>& v) {
    if (v.empty()) return;
    sort(v.begin(), v.end());
    lint sum = 0;
    vector<pair<lint,lint>> tmp;
    for (size_t i = 0; i < v.size(); ++i) {
        sum += v[i].second;
        if (i+1 == v.size() || v[i].first != v[i+1].first) {
            tmp.emplace_back(v[i].first, sum);
            sum = 0;
        }
    }
    v = move(tmp);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> R >> C;
    cin >> pattern;
    for (int i = 0; i <= 60; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; ++j) comb[i][j] = comb[i-1][j-1] + comb[i-1][j];
    }
    N = R + C;
    total = comb[N*2][R*2];
    for (int i = 0; i <= N; ++i)
        for (int j = 0; j <= N; ++j) {
            if (i) gainA[i][j] = comb[i-1][R-1] * (comb[N*2-i][R] - comb[j][R]);
            if (j) gainB[i][j] = comb[j-1][R-1] * (comb[N*2-j][R] - comb[i][R]);
        }
    pathCount[0][0] = 1;
    for (int i = 0; i <= N; ++i)
        for (int j = 0; j <= N; ++j) {
            if (i < N && pattern[i+j] != 'B') pathCount[i+1][j] += pathCount[i][j];
            if (j < N && pattern[i+j] != 'A') pathCount[i][j+1] += pathCount[i][j];
        }
    for (int k = R; k <= N; ++k) {
        if (pattern[k+R-1] != 'B') buildPaths(R, k, gainA[R][k], comb[k+R-1][R-1], pathCount[R-1][k], false);
        if (pattern[k+R-1] != 'A') buildPaths(k, R, gainB[k][R], comb[k+R-1][R-1], pathCount[k][R-1], true);
    }
    for (int i = R; i <= N; ++i)
        for (int d = 0; d < 2; ++d) {
            combine(leftPaths[i][d]);
            combine(rightPaths[i][d]);
        }
    minDelta = total + 1;
    forwardScan(N, N, 0, false);
    forwardScan(N, N, 0, true);
    backwardScan(N, N, 0, false);
    backwardScan(N, N, 0, true);
    cout << result << '\n';
}
